def transform(grid):
    h, w = len(grid), len(grid[0])

    # Locate a full row or column that acts as the divider.
    for r in range(h):
        if len(set(grid[r])) == 1 and grid[r][0] != 0:
            return [
                [2 if grid[i][j] != 0 and grid[i + r + 1][j] != 0 else 0
                 for j in range(w)]
                for i in range(r)
            ]

    for c in range(w):
        if all(grid[r][c] != 0 for r in range(h)) and len({grid[r][c] for r in range(h)}) == 1:
            return [
                [2 if grid[r][j] != 0 and grid[r][j + c + 1] != 0 else 0
                 for j in range(c)]
                for r in range(h)
            ]

    return grid
